/bin/bash -lc "python3 - <<'PY'
import zipfile, re
p='/home/user/Desktop/New_Club_Spring_2018_Training.pptx'
with zipfile.ZipFile(p) as z:
    for name in z.namelist():
        if re.fullmatch(r'ppt/slides/slide\\d+\\.xml', name):
            txt=z.read(name).decode('utf-8', 'ignore')
            if 'Providing another perspective' in txt or 'Advocating for student Budget Requests' in txt:
                print(name)
                for m in re.finditer(r'<a:t>(.*?)</a:t>', txt):
                    t=m.group(1)
                    if any(s in t for s in ['Providing another perspective','Advocating for student Budget Requests','Tracking budgets']):
                        print(' ',t)
PY"

